
#nullable enable

namespace tryAGI.OpenAI
{
    /// <summary>
    /// The quality of the image generated by the image generation tool call. One of `low`, `medium`, `high`, `xhigh`, `max`, or `auto`.
    /// </summary>
    public enum BetaImageGenToolCallQuality
    {
        /// <summary>
        ///
        /// </summary>
        Auto,
        /// <summary>
        ///
        /// </summary>
        High,
        /// <summary>
        ///
        /// </summary>
        Low,
        /// <summary>
        ///
        /// </summary>
        Max,
        /// <summary>
        ///
        /// </summary>
        Medium,
        /// <summary>
        ///
        /// </summary>
        Xhigh,
    }

    /// <summary>
    /// Enum extensions to do fast conversions without the reflection.
    /// </summary>
    public static class BetaImageGenToolCallQualityExtensions
    {
        /// <summary>
        /// Converts an enum to a string.
        /// </summary>
        public static string ToValueString(this BetaImageGenToolCallQuality value)
        {
            return value switch
            {
                BetaImageGenToolCallQuality.Auto => "auto",
                BetaImageGenToolCallQuality.High => "high",
                BetaImageGenToolCallQuality.Low => "low",
                BetaImageGenToolCallQuality.Max => "max",
                BetaImageGenToolCallQuality.Medium => "medium",
                BetaImageGenToolCallQuality.Xhigh => "xhigh",
                _ => throw new global::System.ArgumentOutOfRangeException(nameof(value), value, null),
            };
        }
        /// <summary>
        /// Converts an string to a enum.
        /// </summary>
        public static BetaImageGenToolCallQuality? ToEnum(string value)
        {
            return value switch
            {
                "auto" => BetaImageGenToolCallQuality.Auto,
                "high" => BetaImageGenToolCallQuality.High,
                "low" => BetaImageGenToolCallQuality.Low,
                "max" => BetaImageGenToolCallQuality.Max,
                "medium" => BetaImageGenToolCallQuality.Medium,
                "xhigh" => BetaImageGenToolCallQuality.Xhigh,
                _ => null,
            };
        }
    }
}